const NOW = Date.parse("2026-11-10T15:00:00");   // a Tuesday
let seed = 20261112 + 7919 * +(process.env.SEED_SHIFT || 0); const rnd = () => { let t = (seed += 0x6D2B79F5); t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const pick = (a) => a[Math.floor(rnd() * a.length)];
const int = (a, b) => a + Math.floor(rnd() * (b - a + 1));
const TOTAL = +(process.argv[2] || 10000);
const arD = (s) => String(s).replace(/\d/g, (d) => "٠١٢٣٤٥٦٧٨٩"[d]);
// an amount and the ways it is written: 1250 → "1,250.00" · "1250" · "1,250" · "1250.00"; sometimes with piastres
const money = (lo = 20, hi = 9000) => { const whole = int(lo, hi), cents = rnd() < 0.25 ? pick([0.5, 0.25, 0.75, 0.99]) : 0, v = whole + cents;
  const two = v.toFixed(2), grp = (s) => s.replace(/\B(?=(\d{3})+(?!\d))/g, ","), [i, f] = two.split(".");
  const s = cents ? pick([grp(i) + "." + f, i + "." + f]) : pick([grp(i) + ".00", i, grp(i), i + ".00"]);
  return { v, s, ar: arD(s).replace(".", "٫").replace(/,/g, "٬") }; };
const t4 = () => String(int(1000, 9999)), ref = () => String(int(100000, 99999999)), code = () => String(int(100000, 999999)), phone = () => "010" + int(10000000, 99999999);
