// ---- 4 thirty countries, their languages: the world corpus with new amounts (the READER must not depend on one number) -------------
function reAmount(text, amt) {   // find the amount as written, write another one the same way
  for (const m of text.matchAll(/\d[\d.,٬'  ]*\d|\d/g)) { const tok = m[0].trim();
    const dec = /^(.*?)([.,])(\d{1,3})$/.exec(tok); let intPart = tok, sep = "", frac = "";
    if (dec && Math.abs(parseFloat(dec[1].replace(/\D/g, "") + "." + dec[3]) - amt) < 0.0005 && !(dec[3].length === 3 && Math.abs(parseFloat(tok.replace(/\D/g, "")) - amt) < 0.0005)) { intPart = dec[1]; sep = dec[2]; frac = dec[3]; }
    else if (Math.abs(parseFloat(tok.replace(/\D/g, "")) - amt) > 0.0005) continue;
    const th = (/\D/.exec(intPart) || [""])[0], whole = int(11, intPart.replace(/\D/g, "").length >= 5 ? 90000 : 4800), fr = frac ? (frac.length === 3 ? pick(["000", "500", "250"]) : pick(["00", "00", "50", "99"])) : "";
    const useTh = th || (frac && sep === "," ? " " : frac ? "," : ""), wholeS = whole >= 1000 && (th || rnd() < 0.5) && useTh ? String(whole).replace(/\B(?=(\d{3})+(?!\d))/g, useTh) : String(whole);
    return { text: text.slice(0, m.index) + wholeS + (frac ? sep + fr : "") + text.slice(m.index + m[0].length).replace(/^/, m[0].endsWith(" ") ? " " : ""), v: whole + (fr ? +("0." + fr) : 0) }; }
  return null; }
